#include <gtest/gtest.h>
#include "c36_runtime_adapter.hpp"
using namespace c36_runtime;
class Bridge:public ::testing::Test {
 protected:
  c36::Owner owner{"publisher-run","boot","publisher-instance",std::string(64,'a'),0};
  Adapter a{owner,"observer-run",std::string(64,'b'),std::string(64,'c')};p1::Job j;
  usv_research_interfaces::msg::AppliedControl applied(uint64_t sequence=1,double n=0,int64_t start=1000){usv_research_interfaces::msg::AppliedControl m;m.event_semantics="publisher_command";m.run_id=owner.run;m.producer_instance_id=owner.producer;m.config_hash=owner.config;m.sequence=sequence;m.final_n={n,n};m.left_publish_success=m.right_publish_success=true;m.left_publish_start_steady_ns=start;m.left_publish_end_steady_ns=start+10;m.right_publish_start_steady_ns=start+1000;m.right_publish_end_steady_ns=start+1010;return m;}
  void SetUp()override{ASSERT_TRUE(bool(a.observe(applied(),3000)));j.run_id="observer-run";j.boot_id=owner.boot;j.contract_hash=std::string(64,'b');j.nominal_hash=std::string(64,'c');j.anchor_source="legacy_publisher";j.anchor_run_id=owner.run;j.anchor_producer=owner.producer;j.job_id=1;j.target_tick=1;j.tick_origin_steady_ns=10000000;j.freeze_steady_ns=10000001;j.deadline_steady_ns=160000000;j.target_steady_ns=210000000;j.model_generation=j.config_generation=j.schedule_generation=1;j.anchor_n={0,0};j.anchor_sequence={1,1};j.anchor_publish_ns={1000,2000};j.anchor_known={true,true};j.target_state={1,2,3,4,5,6};}
  void commit(){ASSERT_TRUE(bool(a.submit(j,11000000)));ASSERT_TRUE(bool(a.ready(j,{1,2},20000000)));ASSERT_TRUE(bool(a.cutoff(160000001)));}
};
TEST_F(Bridge,ImportsActualNonzeroPredictionWithoutReplacingEarlierAnchor){ASSERT_TRUE(bool(a.observe(applied(2,3,10500000),10502000)));ASSERT_TRUE(bool(a.submit(j,11000000)));ASSERT_TRUE(bool(a.ready(j,{1,2},20000000)));ASSERT_TRUE(bool(a.cutoff(160000001)));EXPECT_EQ(a.inspect(1,1,210000000).reason,"anchor_mismatch");EXPECT_FALSE(a.facts().active_transaction);}
TEST_F(Bridge,SameValueCompleteHistoryPassesAndNeverCreatesOutputTransaction){commit();ASSERT_TRUE(bool(a.observe(applied(2,0,180000000),180002000)));EXPECT_TRUE(bool(a.inspect(1,1,210000000)));EXPECT_FALSE(a.facts().active_transaction);EXPECT_TRUE(bool(a.observe(applied(3,2,220000000),220002000)));}
TEST_F(Bridge,FullEchoIncludesReferenceAndHistory){ASSERT_TRUE(bool(a.submit(j,11000000)));auto forged=j;forged.reference[20]=2;EXPECT_EQ(a.ready(forged,{1,2},20000000).reason,"full_job_echo_mismatch");forged=j;forged.history_n.push_back(1);EXPECT_EQ(a.ready(forged,{1,2},20000000).reason,"full_job_echo_mismatch");}
TEST_F(Bridge,MissingCandidateExpiresSlotAndNextJobEnters){ASSERT_TRUE(bool(a.submit(j,11000000)));ASSERT_TRUE(bool(a.cancel(1,210000000)));j.job_id=2;j.target_tick=2;j.tick_origin_steady_ns=220000000;j.freeze_steady_ns=220000001;j.deadline_steady_ns=370000000;j.target_steady_ns=420000000;EXPECT_TRUE(bool(a.submit(j,230000000)));}
TEST_F(Bridge,ExternalGuardRejectionCancelsReadySlot){commit();ASSERT_TRUE(bool(a.cancel(1,210000000)));EXPECT_EQ(a.inspect(1,1,210000001).reason,"adapter_job_missing");EXPECT_FALSE(a.evidence()["job_pending"].get<bool>());}
TEST_F(Bridge,ScheduleResetAllowsNewTickButJobIdRemainsMonotonic){commit();ASSERT_TRUE(bool(a.cancel(0,210000000)));j.schedule_generation=2;j.job_id=2;j.tick_origin_steady_ns=220000000;j.freeze_steady_ns=220000001;j.deadline_steady_ns=370000000;j.target_steady_ns=420000000;EXPECT_TRUE(bool(a.submit(j,230000000)));}
TEST_F(Bridge,ClosingInhibitsSubmissionAndReadinessButRetainsAuthenticatedTail){commit();ASSERT_TRUE(bool(a.request_close(180000000)));EXPECT_EQ(a.ready(j,{1,2},190000000).reason,"driver_close_requested");EXPECT_EQ(a.inspect(1,1,210000000).reason,"driver_close_requested");ASSERT_TRUE(bool(a.observe(applied(2,0,220000000),220002000)));EXPECT_EQ(a.evidence()["command_sequence"],(std::array<uint64_t,2>{2,2}));EXPECT_FALSE(a.facts().active_transaction);ASSERT_TRUE(bool(a.close_after_join(230000000)));EXPECT_EQ(a.facts().life,c36::Life::closed);}
TEST_F(Bridge,RejectedCancelDoesNotHideAnOrphanSlot){ASSERT_TRUE(bool(a.submit(j,11000000)));EXPECT_EQ(a.cancel(0,1).reason,"time_order");EXPECT_TRUE(a.evidence()["job_pending"].get<bool>());EXPECT_TRUE(bool(a.ready(j,{1,2},20000000)));}
TEST_F(Bridge,FailedCloseDoesNotClaimComponentClosed){ASSERT_TRUE(bool(a.submit(j,11000000)));EXPECT_EQ(a.close_after_join(1).reason,"time_order");EXPECT_NE(a.facts().life,c36::Life::closed);EXPECT_TRUE(a.evidence()["job_pending"].get<bool>());EXPECT_TRUE(a.closing());}
TEST_F(Bridge,ForeignPayloadCannotAdvanceAnchor){auto m=applied(2,3,5000);m.producer_instance_id="foreign";EXPECT_EQ(a.observe(m,7000).reason,"payload_owner_mismatch");EXPECT_EQ(a.facts().anchor.seq[0],1u);}
TEST_F(Bridge,LateReadyRejectedAndZeroDefaultPredictionIsNotSynthesized){ASSERT_TRUE(bool(a.submit(j,11000000)));EXPECT_EQ(a.ready(j,{1,2},160000001).reason,"ready_time");}
TEST_F(Bridge,ForgedEarlierAnchorNotInHistoryRejected){j.anchor_n={2,2};EXPECT_EQ(a.submit(j,11000000).reason,"frozen_anchor_not_in_authenticated_history");}
TEST_F(Bridge,FutureOrChangedFreezeTimingRejected){j.freeze_steady_ns=20000000;EXPECT_EQ(a.submit(j,11000000).reason,"freeze_time");}
TEST_F(Bridge,OwnerEpochChangeRequiresNewSession){j.clock_epoch=1;EXPECT_EQ(a.submit(j,11000000).reason,"version_time_or_epoch");}
TEST_F(Bridge,FinalReadyCompletionExactlyAtDeadlinePasses){ASSERT_TRUE(bool(a.submit(j,11000000)));ASSERT_TRUE(bool(a.ready(j,{1,2},20000000)));EXPECT_TRUE(bool(a.finalize_ready_completion(1,j.deadline_steady_ns)));EXPECT_TRUE(bool(a.cutoff(j.deadline_steady_ns+1)));EXPECT_TRUE(bool(a.inspect(1,1,j.target_steady_ns)));EXPECT_FALSE(a.facts().active_transaction);}
TEST_F(Bridge,PreliminaryReadyCannotHideDeadlineCrossing){ASSERT_TRUE(bool(a.submit(j,11000000)));ASSERT_TRUE(bool(a.ready(j,{1,2},j.deadline_steady_ns-1)));EXPECT_EQ(a.finalize_ready_completion(1,j.deadline_steady_ns+1).reason,"late_ready_completion");EXPECT_FALSE(a.evidence()["job_pending"].get<bool>());EXPECT_EQ(a.cutoff(j.deadline_steady_ns+2).reason,"no_ready_or_duplicate_cutoff");j.job_id=2;j.target_tick=2;j.tick_origin_steady_ns=220000000;j.freeze_steady_ns=220000001;j.deadline_steady_ns=370000000;j.target_steady_ns=420000000;EXPECT_TRUE(bool(a.submit(j,230000000)));}
TEST_F(Bridge,CompletionBackwardsTimeCannotHideReadySlot){ASSERT_TRUE(bool(a.submit(j,11000000)));ASSERT_TRUE(bool(a.ready(j,{1,2},20000000)));EXPECT_EQ(a.finalize_ready_completion(1,19000000).reason,"time_order");EXPECT_TRUE(a.evidence()["job_pending"].get<bool>());EXPECT_TRUE(bool(a.finalize_ready_completion(1,21000000)));}
